// 做法：从左往右贪心。设前一个位置的最终值为 pre，每个位置只有两个候选
//       （保持 a_i，或改成 b_1 - a_i），取「不小于 pre 的候选里最小的那个」，
//       这样给后面留的余地最大；两个候选都小于 pre 就无解。
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;
    while (t--) {
        int n, m;
        cin >> n >> m;

        vector<long long> a(n);
        for (int i = 0; i < n; ++i) cin >> a[i];

        vector<long long> b(m);
        for (int i = 0; i < m; ++i) cin >> b[i];

        long long pre = LLONG_MIN / 4;   // 上一个位置的最终值；首元素没有下界
        bool ok = true;

        for (int i = 0; i < n; ++i) {
            long long keep = a[i];               // 候选一：不操作
            long long change = b[0] - a[i];      // 候选二：操作一次（m = 1，只有 b_1）
            long long lo = min(keep, change);
            long long hi = max(keep, change);

            if (lo >= pre) {
                pre = lo;                        // 小的那个就够大，取它
            } else if (hi >= pre) {
                pre = hi;                        // 只能退而取大的那个
            } else {
                ok = false;                      // 两个都小于 pre，本组无解
                break;
            }
        }

        cout << (ok ? "YES" : "NO") << '\n';
    }
    return 0;
}
```

### 易错点

允许操作出零或负数，初始下界不能设成零。

